+
+      .option input {
+        margin-top: 2px;
+        width: 18px;
+        height: 18px;
+        accent-color: var(--accent);
+      }
+
+      .option span {
+        line-height: 1.5;
+      }
+
+      .actions {
+        display: flex;
+        justify-content: flex-end;
+        margin-top: 24px;
+      }
+
+      button {
+        appearance: none;
+        border: 0;
+        border-radius: 999px;
+        padding: 14px 22px;
+        font: inherit;
+        font-weight: 700;
+        color: white;
