+
+      @media (max-width: 640px) {
+        .quiz-header,
+        form {
+          padding-left: 18px;
+          padding-right: 18px;
+        }
+
+        .form-field {
+          padding: 18px;
+        }
+      }
+    </style>
+  </head>
+  <body>
