<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Computer Languages Quiz</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: rgba(17, 24, 39, 0.92);
        --panel-border: rgba(148, 163, 184, 0.2);
        --text: #e5eefb;
        --muted: #9fb0c7;
        --accent: #7c9cff;
        --accent-2: #22d3ee;
        --focus: #a5b4fc;
        --shadow: 0 24px 60px rgba(0, 0, 0, 0.42);
        --radius: 20px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 35%),
          radial-gradient(circle at bottom right, rgba(34, 211, 238, 0.12), transparent 25%),
          var(--bg);
        color: var(--text);
        display: grid;
        place-items: center;
        padding: 24px;
      }

      .app {
        width: min(900px, 100%);
      }

      .quiz-shell {
        background: linear-gradient(180deg, rgba(19, 27, 46, 0.96), rgba(11, 16, 32, 0.98));
        border: 1px solid var(--panel-border);
        border-radius: calc(var(--radius) + 8px);
        box-shadow: var(--shadow);
        overflow: hidden;
      }

      .quiz-header {
        padding: 32px 32px 8px;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 8px 12px;
        border-radius: 999px;
        background: rgba(124, 156, 255, 0.12);
        color: #cfd8ff;
        font-size: 0.85rem;
        letter-spacing: 0.04em;
        text-transform: uppercase;
      }

      h1 {
        margin: 18px 0 10px;
        font-size: clamp(2rem, 4vw, 3rem);
        line-height: 1.05;
      }

      .subtitle {
        margin: 0;
        max-width: 60ch;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.6;
      }

      form {
        padding: 20px 32px 32px;
      }

      .form-field {
        margin-top: 20px;
        padding: 22px;
        border: 1px solid rgba(148, 163, 184, 0.14);
        border-radius: var(--radius);
        background: rgba(15, 23, 42, 0.72);
      }

      .question-title {
        margin: 0 0 8px;
        font-size: 1.1rem;
      }

      .help-text {
        margin: 0 0 16px;
        color: var(--muted);
        font-size: 0.95rem;
        line-height: 1.5;
      }

      .options {
        display: grid;
        gap: 12px;
      }

      .option {
        display: flex;
        align-items: flex-start;
        gap: 12px;
        padding: 14px 16px;
        border: 1px solid rgba(148, 163, 184, 0.16);
        border-radius: 16px;
        background: rgba(255, 255, 255, 0.03);
        transition: border-color 0.2s ease, background 0.2s ease, transform 0.2s ease;
        cursor: pointer;
      }

      .option:hover {
        border-color: rgba(124, 156, 255, 0.45);
        background: rgba(124, 156, 255, 0.08);
        transform: translateY(-1px);
      }

      .option input {
        margin-top: 2px;
        width: 18px;
        height: 18px;
        accent-color: var(--accent);
      }

      .option span {
        line-height: 1.5;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
        margin-top: 24px;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 14px 22px;
        font: inherit;
        font-weight: 700;
        color: white;
        background: linear-gradient(135deg, var(--accent), var(--accent-2));
        box-shadow: 0 14px 30px rgba(34, 211, 238, 0.18);
        cursor: pointer;
      }

      button:focus-visible,
      input:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .result {
        margin-top: 20px;
        padding: 16px 18px;
        border-radius: 16px;
        background: rgba(34, 211, 238, 0.08);
        border: 1px solid rgba(34, 211, 238, 0.22);
        color: #d6fbff;
      }

      @media (max-width: 640px) {
        .quiz-header,
        form {
          padding-left: 18px;
          padding-right: 18px;
        }

        .form-field {
          padding: 18px;
        }
      }
    </style>
  </head>
  <body>
    <div id="root" class="app"></div>

    <script>
      const quizData = [
        {
          id: "q1",
          question: "Which of these are programming languages?",
          helpText: "Select all options that are used to write software.",
          options: ["JavaScript", "Python", "HTML", "CSS"],
        },
        {
          id: "q2",
          question: "Which of these are compiled languages?",
          options: ["C", "Rust", "JavaScript", "Go"],
        },
        {
          id: "q3",
          question: "Which of these are scripting languages?",
          options: ["Bash", "Python", "C++", "Ruby"],
        },
      ];

      function createOption(questionId, optionText, index) {
        const optionId = `${questionId}-${index}`;
        return `
          <label class="option" for="${optionId}">
            <input id="${optionId}" type="checkbox" name="${questionId}" value="${optionText}" />
            <span>${optionText}</span>
          </label>
        `;
      }

      function createQuestionField(question) {
        return `
          <div class="form-field">
            <h2 class="question-title">${question.question}</h2>
            ${question.helpText ? `<p class="help-text">${question.helpText}</p>` : ""}
            <div class="options" role="group" aria-label="${question.question}">
              ${question.options.map((option, index) => createOption(question.id, option, index)).join("")}
            </div>
          </div>
        `;
      }

      function QuizApp() {
        return `
          <div class="quiz-shell">
            <header class="quiz-header">
              <div class="eyebrow">Knowledge check</div>
              <h1>Computer Languages Quiz</h1>
              <p class="subtitle">Pick every answer that fits. Each question allows multiple selections.</p>
            </header>
            <form id="quiz-form" novalidate>
              ${quizData.map(createQuestionField).join("")}
              <div class="actions">
                <button type="submit">Submit Quiz</button>
              </div>
              <div id="result" class="result" hidden aria-live="polite"></div>
            </form>
          </div>
        `;
      }

      document.getElementById("root").innerHTML = QuizApp();

      document.getElementById("quiz-form").addEventListener("submit", (event) => {
        event.preventDefault();
        const result = document.getElementById("result");
        const selected = quizData.map((question) => {
          const values = Array.from(
            document.querySelectorAll(`input[name="${question.id}"]:checked`)
          ).map((input) => input.value);
          return `${question.question}: ${values.length ? values.join(", ") : "No selections"}`;
        });

        result.hidden = false;
        result.textContent = selected.join(" | ");
      });
    </script>
  </body>
</html>
